export type sourcesDataLogicType = MakeLogicType<sourcesDataLogicValues, sourcesDataLogicActions>

export const sourcesDataLogic = kea<sourcesDataLogicType>([
    path(['products', 'dataWarehouse', 'sourcesDataLogic']),
    actions({
        abortAnyRunningQuery: true,
        loadSources: true,
        setLastUpdateConnectionWarning: (warning: string | null) => ({ warning }),
    }),
    loaders(({ cache, values, actions }) => ({
        dataWarehouseSources: [
            null as PaginatedResponse<ExternalDataSource> | null,
            {
                loadSources: async (_, breakpoint) => {
                    await breakpoint(300)
                    actions.abortAnyRunningQuery()

                    const controller = new AbortController()
                    cache.abortController = controller
                    const methodOptions: ApiMethodOptions = {
                        signal: cache.abortController.signal,
                    }
                    try {
                        const res = await api.externalDataSources.list(methodOptions)
                        breakpoint()
                        const results = [...res.results]
                        let next = res.next
                        while (next) {
                            // nosemgrep: prefer-codegen-api -- Follows the pagination URL the server returns.
                            const page = await api.get<PaginatedResponse<ExternalDataSource>>(next, methodOptions)
                            breakpoint()
                            results.push(...page.results)
                            next = page.next
                        }
                        cache.abortController = null

                        const response: PaginatedResponse<ExternalDataSource> = { ...res, results, next: null }
                        return response
                    } catch (error: any) {
                        // A superseded request must not clear the newer request's controller.
                        breakpoint()
                        if (cache.abortController === controller) {
                            cache.abortController = null
                        }
                        if (error?.status === 403) {
                            return { results: [], count: 0, next: null, previous: null }
                        }
                        throw error
                    }
                },
                updateSource: async (source: ExternalDataSource) => {
                    const updatedSource = await api.externalDataSources.update(source.id, source)
                    actions.setLastUpdateConnectionWarning(updatedSource.connection_warning ?? null)
                    return {
                        ...values.dataWarehouseSources,
                        results:
                            values.dataWarehouseSources?.results.map((s: ExternalDataSource) =>
                                s.id === updatedSource.id ? updatedSource : s
                            ) || [],
                    }
                },
                updateSourceRevenueAnalyticsConfig: async ({
                    source,
                    config,
                }: {
                    source: ExternalDataSource
                    config: Partial<ExternalDataSourceRevenueAnalyticsConfig>
                }) => {
                    const updatedSource = await api.externalDataSources.updateRevenueAnalyticsConfig(source.id, config)
                    return {
                        ...values.dataWarehouseSources,
                        results:
                            values.dataWarehouseSources?.results.map((s: ExternalDataSource) =>
                                s.id === updatedSource.id ? updatedSource : s
                            ) || [],
                    }
                },
            },
        ],
    })),
    reducers(({ cache }) => ({
        sourcesLoadError: [false, { loadSourcesSuccess: () => false, loadSourcesFailure: () => true }],
        lastUpdateConnectionWarning: [
            null as string | null,
            {
                setLastUpdateConnectionWarning: (_, { warning }) => warning,
            },
        ],
        dataWarehouseSourcesLoading: [
            false as boolean,
            {
                loadSources: () => true,
                loadSourcesFailure: () => cache.abortController !== null,
                loadSourcesSuccess: () => cache.abortController !== null,
            },
        ],
    })),
    listeners(({ cache }) => ({
        abortAnyRunningQuery: () => {
            if (cache.abortController) {
                cache.abortController.abort()
                cache.abortController = null
            }
        },
    })),
])
